import re
def file_name_check(file_name):
    # Check if the file name contains more than three digits
    if len(re.findall(r'\d', file_name)) > 3:
        return 'No'
    # Check if the file name contains exactly one dot
    if file_name.count('.') != 1:
        return 'No'
    # Check if the substring before the dot should not be empty, and it starts with a letter from the latin alphapet
    if not re.match(r'^[a-zA-Z]', file_name.split('.')[0]):
        return 'No'
    # Check if the substring after the dot should be one of these: ['txt', 'exe', 'dll']
    if file_name.split('.')[1] not in ['txt', 'exe', 'dll']:
        return 'No'
    return 'Yes'

